CA = 'Clinical application'
M = 'Management'
D = 'Definitions'
CARDS = {
'eb': [
(0, D, 'Define miscarriage.', 'Spontaneous loss of a pregnancy before 24 weeks (before viability). Abortion is the induced loss of a pregnancy.', 1),
(1, D, 'Define recurrent miscarriage.', 'Three or more consecutive miscarriages.', 1),
(2, 'Causes', 'What are the pregnancy-related causes of bleeding before 24 weeks?', 'Miscarriage (the commonest), ectopic pregnancy (the most dangerous), molar pregnancy and implantation bleeding.', 1),
(3, 'Causes', 'What is the commonest cause of first-trimester miscarriage?', 'Chromosomal abnormality (aneuploidy), which accounts for about half of first-trimester losses.', 1),
(4, 'Types of miscarriage', 'At 10 weeks a woman has light bleeding, a closed os and a live fetus. What is the diagnosis?', 'Threatened miscarriage.', 1),
(5, 'Types of miscarriage', 'A woman has heavy bleeding and colicky pain, with an open os and no tissue passed. What is the diagnosis?', 'Inevitable miscarriage.', 2),
(6, 'Types of miscarriage', 'A woman has bleeding, an open os with tissue felt in it and a uterus that is slightly small. What is the diagnosis?', 'Incomplete miscarriage.', 2),
(7, 'Types of miscarriage', 'Pain and bleeding have settled, the os is closed and the uterus is empty. What must be excluded?', 'Ectopic pregnancy: a previous intrauterine pregnancy must be confirmed, or hCG followed until it is negative.', 3),
(8, 'Types of miscarriage', 'What are the ultrasound criteria for missed miscarriage?', 'A crown–rump length of 7 mm or more with no heartbeat, or a mean sac diameter of 25 mm or more with no embryo.', 2),
(9, M, 'How is threatened miscarriage managed?', 'Reassurance; bed rest and progesterone are of unproven benefit; intercourse is avoided until the bleeding stops.', 1),
(10, M, 'What is the maximum duration of expectant management of missed miscarriage, and why?', 'Four weeks, because a retained dead fetus carries a risk of DIC (consumption coagulopathy).', 3),
(11, 'Drug treatment', 'What is the dose of misoprostol for missed miscarriage before 13 weeks?', '800 µg vaginally or 600 µg sublingually, repeated after 3 hours if needed.', 2),
(12, 'Drug treatment', 'What is the dose of misoprostol for incomplete miscarriage before 13 weeks?', '600 µg orally or 400 µg sublingually, as a single dose.', 2),
(13, 'Drug treatment', 'Why is misoprostol given before surgical evacuation?', 'A dose of 400 µg vaginally 3 hours before the procedure ripens the cervix and prevents cervical tears and cervical weakness.', 2),
(14, 'Complications', 'A woman has amenorrhoea after repeated curettage. What is the diagnosis?', 'Asherman syndrome: intrauterine adhesions caused by excessive curettage.', 2),
(15, 'Septic miscarriage', 'Which antibiotics are given for septic miscarriage?', 'IV ceftriaxone 1–2 g daily plus metronidazole 500 mg 8-hourly, after cultures have been taken, followed by evacuation.', 2),
(16, 'Septic miscarriage', 'Which organism is suggested by septic abortion with jaundice and haematuria?', 'Clostridium welchii, which causes haemolysis.', 3),
(17, 'Recurrent miscarriage', 'What is the most important treatable cause of recurrent miscarriage, and how is it treated?', 'Antiphospholipid syndrome, treated with aspirin 75 mg plus low-molecular-weight heparin (for example enoxaparin 40 mg daily).', 2),
(18, 'Recurrent miscarriage', 'A woman has painless second-trimester losses, each earlier than the last. What are the cause and treatment?', 'Cervical weakness; history-indicated cervical cerclage at 12–14 weeks.', 2),
(19, 'Recurrent miscarriage', 'When is a cervical cerclage removed?', 'At 37–38 weeks, or earlier if there is labour, rupture of membranes, bleeding, infection or fetal death.', 2),
(20, 'Ectopic pregnancy', 'What is the commonest site of ectopic pregnancy?', 'The ampulla of the fallopian tube.', 1),
(21, 'Ectopic pregnancy', 'What is the most important risk factor for tubal ectopic pregnancy?', 'Pelvic inflammatory disease (tubal damage); a previous ectopic pregnancy is also a strong risk factor.', 1),
(22, 'Ectopic pregnancy', 'What is the discriminatory zone?', 'The hCG level (2000 IU/L on transvaginal ultrasound, about 6000 IU/L on abdominal ultrasound) above which an intrauterine sac should be visible.', 2),
(23, 'Ectopic pregnancy', 'How does hCG change over 48 hours in a normal intrauterine pregnancy and in an ectopic pregnancy?', 'In a normal pregnancy it rises by at least 63% (approximately doubles); in an ectopic pregnancy it rises slowly or remains at the same level.', 2),
(24, 'Ectopic pregnancy', 'What is the dose of methotrexate for ectopic pregnancy, and how is success assessed?', '50 mg/m² IM as a single dose; hCG should fall by 15% or more between day 4 and day 7.', 3),
(25, 'Ectopic pregnancy', 'What are the contraindications to methotrexate for ectopic pregnancy?', 'Haemodynamic instability, rupture, hCG above 5000 IU/L, a mass larger than 3.5 cm, a live embryo and inability to attend follow-up.', 3),
(26, 'Ectopic pregnancy', 'How is the choice made between salpingectomy and salpingotomy?', 'Salpingectomy is performed if the other tube is healthy; salpingotomy if it is damaged (hCG follow-up is then required).', 3),
(27, 'Ectopic pregnancy', 'A woman is in shock with a positive pregnancy test and a distended abdomen. What is the next step?', 'Resuscitation and immediate laparotomy with salpingectomy, without waiting for an ultrasound scan.', 2),
(28, 'Molar pregnancy', 'What are the karyotypes of complete and partial hydatidiform mole?', 'Complete mole: 46,XX (an empty ovum; paternal chromosomes only). Partial mole: 69,XXY triploid (two sperm).', 2),
(29, 'Molar pregnancy', 'Why is misoprostol not given before evacuation of a molar pregnancy?', 'Contractions can cause embolisation of trophoblast; suction evacuation with dilators is used, and oxytocin is given only after emptying has started.', 3),
(30, 'Molar pregnancy', 'How is hCG followed up after evacuation of a molar pregnancy?', 'Every 2 weeks until normal. If hCG is normal within 56 days, follow-up continues for 6 months from evacuation; otherwise for 6 months from normalisation.', 3),
(31, 'Anti-D', 'When is anti-D given in early pregnancy to an RhD-negative woman?', '250 IU IM within 72 hours (before 20 weeks) for ectopic pregnancy, partial mole, any miscarriage at 10 weeks or more, surgical evacuation before 10 weeks, and heavy or repeated threatened bleeding. A complete mole does not require it.', 3),
],
'ap': [
(0, D, 'Define antepartum haemorrhage.', 'Bleeding from the genital tract after 28 weeks and before the end of the second stage of labour.', 1),
(1, D, 'Define placenta praevia.', 'A placenta that is implanted wholly or partly in the lower uterine segment.', 1),
(2, D, 'Define placental abruption.', 'Premature separation of a normally situated placenta before delivery of the baby.', 1),
(3, D, 'What is the difference between major and minor placenta praevia?', 'Major placenta praevia covers the internal os; minor placenta praevia lies in the lower segment but does not cover the os.', 1),
(4, D, 'Define placenta accreta, increta and percreta.', 'The villi attach to the myometrium (accreta), invade it (increta) or penetrate through the uterine wall, sometimes into the bladder (percreta).', 2),
(5, 'Clinical scenarios', 'At 32 weeks a woman has painless bright red bleeding, a soft non-tender uterus and a breech presentation. What are the diagnosis and next step?', 'Placenta praevia. She is resuscitated and the diagnosis is confirmed by ultrasound; digital vaginal examination is not performed.', 2),
(6, 'Clinical scenarios', 'At 34 weeks a woman with pre-eclampsia has sudden constant pain, a woody-hard uterus, little vaginal bleeding and a falling blood pressure. What is the diagnosis?', 'Concealed placental abruption. She is resuscitated, the clotting is corrected and she is delivered.', 2),
(7, 'Clinical scenarios', 'The membranes rupture, followed by slight painless bleeding and sudden fetal bradycardia; the mother is well. What are the diagnosis and action?', 'Vasa praevia. Immediate caesarean section, with the neonatal team and blood ready.', 3),
(8, 'Clinical scenarios', 'A woman with a previous caesarean section receives oxytocin in labour; she has sudden pain, the contractions stop, the head recedes and she is in shock. What are the diagnosis and action?', 'Uterine rupture. Resuscitation and immediate laparotomy.', 2),
(9, 'Clinical scenarios', 'In placental abruption with confirmed fetal death and a stable mother, what is the mode of delivery?', 'Vaginal delivery, with artificial rupture of membranes and oxytocin after the clotting has been corrected; labour is usually rapid.', 3),
(10, 'Clinical scenarios', 'In placental abruption with a live fetus and fetal distress, what is the action?', 'Emergency caesarean section once resuscitation has started.', 2),
(11, 'Pathophysiology', 'Why is the bleeding in placenta praevia painless?', 'The placenta separates from the stretching lower segment; there are no contractions and no clot pressing on the uterus.', 2),
(12, 'Pathophysiology', 'Why does the lower segment bleed heavily in placenta praevia?', 'It contains few muscle fibres, so it cannot compress the venous sinuses (there are no living ligatures).', 3),
(13, 'Pathophysiology', 'Why is shock out of proportion to the visible loss in placental abruption?', 'Much of the blood is concealed behind the placenta and within the myometrium.', 2),
(14, 'Pathophysiology', 'Why does placental abruption cause DIC?', 'Decidual thromboplastin enters the maternal circulation and consumes fibrinogen, platelets and clotting factors.', 3),
(15, 'Pathophysiology', 'Why are placenta praevia and placenta accreta associated?', 'A scarred lower segment has poor decidua, so the villi invade too deeply.', 3),
(16, 'Pathophysiology', 'Why is digital vaginal examination dangerous in antepartum haemorrhage?', 'The examining finger can disrupt a placenta praevia and cause very heavy bleeding.', 1),
(17, 'Pathophysiology', 'What is a Couvelaire uterus, and what is its risk?', 'Blood infiltrates the myometrium (a blue, bruised uterus); poor contraction causes atony and PPH.', 3),
(18, 'Key figures', 'What is the risk of placenta accreta with placenta praevia and 0, 1, 2 and 3 or more previous caesarean sections?', 'About 3%, 11%, 40% and 60% respectively.', 3),
(19, 'Key figures', 'When is the scan repeated for a placenta that is low at 20 weeks?', 'At 32 weeks; most placentas move upwards as the lower segment develops.', 2),
(20, 'Key figures', 'When is elective caesarean section performed for asymptomatic major placenta praevia?', 'At 37–38 weeks.', 1),
(21, 'Key figures', 'When is a woman with known placenta accreta spectrum delivered?', 'By planned caesarean section at 36 weeks, by a team able to perform hysterectomy.', 2),
(22, 'Key figures', 'When is a woman with known vasa praevia delivered?', 'By elective caesarean section at 34–36 weeks, before the membranes rupture.', 2),
(23, 'Key figures', 'What distance of the placental edge from the internal os allows a trial of vaginal delivery?', 'More than 2 cm.', 2),
(24, 'Key figures', 'How many units of blood are cross-matched in heavy antepartum haemorrhage?', 'Four units for abruption and antepartum haemorrhage in general; 6–8 units for placenta praevia or accreta.', 2),
(25, 'Drug treatment', 'What dose of anti-D is given in antepartum haemorrhage to an RhD-negative woman?', '500 IU IM within 72 hours, with a Kleihauer test to decide whether more is needed; if the Kleihauer test is not available, 1500 IU is given.', 2),
(26, 'Drug treatment', 'What is the dose of FFP for DIC in placental abruption?', '15 mL/kg, with cryoprecipitate, and platelets if she is bleeding with a count below 50 × 10⁹/L.', 3),
(27, 'Drug treatment', 'What is the dose of tranexamic acid in antepartum haemorrhage with continuing bleeding?', '1 g IV.', 1),
(28, 'Investigations', 'What is the bedside clotting test?', '5 mL of blood is placed in a plain tube; failure to clot within 7–10 minutes indicates a low fibrinogen.', 2),
(29, 'Investigations', 'What is the Apt test?', 'It distinguishes fetal from maternal blood: fetal haemoglobin resists alkali and remains pink (used in vasa praevia).', 3),
(30, 'Investigations', 'How are placenta praevia and placental abruption diagnosed?', 'Placenta praevia is diagnosed by ultrasound; abruption is a clinical diagnosis (ultrasound shows the clot in only about 25%).', 2),
(31, 'Complications', 'What is the commonest fetal complication of placenta praevia?', 'Prematurity.', 1),
(32, 'Complications', 'The placenta does not separate at caesarean section for placenta praevia. What must not be done?', 'It must not be pulled; hysterectomy is performed with the placenta in place, or the placenta is left in situ.', 3),
(33, M, 'In uterine rupture, when is repair chosen and when hysterectomy?', 'A clean tear is repaired if the woman wishes to have more children; hysterectomy is performed if the tear is irregular, extends to the cervix or broad ligament, or she is unstable.', 3),
(34, M, 'How is antepartum haemorrhage managed at a peripheral facility?', 'An IV cannula, fluids, oxygen and left lateral tilt, then transfer with a midwife, a referral note and a blood sample. Transfer is not delayed for investigations.', 2),
(37, CA, 'What is the commonest type of placenta accreta spectrum?', 'Placenta accreta (about 75%).', 1),
],
'pph': [
(0, D, 'Define primary postpartum haemorrhage.', 'Blood loss of 500 mL or more after vaginal delivery, or 1000 mL or more at caesarean section, within 24 hours; or any loss that causes haemodynamic instability.', 1),
(1, D, 'Define secondary postpartum haemorrhage.', 'Abnormal or heavy bleeding from the genital tract between 24 hours and 12 weeks after delivery.', 1),
(2, D, 'What is the difference between minor and major PPH?', 'Minor: 500–1000 mL with a stable mother. Major: more than 1000 mL, or any shock.', 1),
(3, 'Causes', 'What are the four Ts of PPH?', 'Tone (atony), Trauma (tears, rupture, inversion), Tissue (retained placenta) and Thrombin (coagulopathy).', 1),
(4, 'Causes', 'What is the commonest cause of primary PPH?', 'Uterine atony, which accounts for about 70% of cases.', 1),
(5, 'Causes', 'The uterus is hard and well contracted, but bright red bleeding continues. What is the cause?', 'Genital tract trauma; cervical, vaginal and perineal tears are looked for.', 2),
(6, 'Risk factors', 'Why do twin pregnancy and polyhydramnios cause PPH?', 'Overdistension: a stretched uterus contracts poorly (atony).', 2),
(7, 'Risk factors', 'Which drugs used in labour relax the uterus and increase the risk of PPH?', 'Magnesium sulphate, nifedipine, beta-mimetics, indomethacin and halogenated anaesthetic agents.', 3),
(8, 'Risk factors', 'Which obstetric conditions cause DIC that leads to PPH?', 'Placental abruption, pre-eclampsia and HELLP syndrome, intrauterine fetal death, sepsis and amniotic fluid embolism.', 2),
(9, 'Pathophysiology', 'What are the "living ligatures"?', 'The criss-cross myometrial fibres that compress the spiral vessels after the placenta separates.', 2),
(10, 'Clinical features', 'Which vital sign changes first in PPH?', 'Tachycardia; the blood pressure falls late, after about 30% of the blood volume has been lost.', 2),
(11, 'Investigations', 'What is the result of the bedside clotting test in coagulopathy?', 'No clot forms in a plain tube within 7–10 minutes.', 2),
(12, M, 'What are the first steps in major PPH?', 'Call for help; airway, breathing and circulation; oxygen 15 L/min; two 14–16 G cannulae; blood tests and cross-match; warmed fluids; and uterine massage.', 1),
(13, M, 'What is the dose of oxytocin for PPH?', '10 IU by slow IV injection, then 40 IU in 500 mL over 4 hours; 5 IU in cardiac disease.', 2),
(14, 'Drug treatment', 'What are the dose and contraindications of ergometrine?', '0.5 mg IM or by slow IV injection; it is avoided in hypertension, pre-eclampsia and heart disease.', 2),
(15, 'Drug treatment', 'What is the dose of misoprostol in PPH?', '800 µg (4 × 200 µg) sublingually, or rectally if she cannot swallow.', 2),
(16, 'Drug treatment', 'What are the dose and contraindication of carboprost?', '250 µg by deep IM injection every 15 minutes, to a maximum of 8 doses; it is avoided in asthma (bronchospasm).', 2),
(17, 'Drug treatment', 'What are the dose and time limit of tranexamic acid in PPH?', '1 g IV over 10 minutes, within 3 hours of delivery; there is no benefit later.', 2),
(18, 'Mechanical measures', 'How is bimanual compression performed?', 'One fist is placed in the anterior fornix and the other hand presses the fundus down onto it.', 2),
(19, 'Mechanical measures', 'Which devices and volume are used for balloon tamponade?', 'A Bakri balloon, Sengstaken tube or condom catheter, filled with 300–500 mL of saline for 12–24 hours.', 2),
(20, 'Surgery', 'What is the order of surgical measures for atony that does not respond to drugs and balloon tamponade?', 'B-Lynch suture, uterine artery ligation, internal iliac artery ligation and finally hysterectomy.', 3),
(21, 'Surgery', 'What is the first uterus-conserving operation for atony at laparotomy?', 'The B-Lynch brace suture, with a success rate of about 90%.', 2),
(22, 'Retained placenta', 'Define retained placenta.', 'A placenta that is not delivered within 30 minutes of birth with active management, or 60 minutes with physiological management.', 1),
(23, 'Retained placenta', 'How is retained placenta managed?', 'Oxytocin, emptying of the bladder, and then manual removal under anaesthesia in theatre with antibiotic cover.', 2),
(24, 'Trauma', 'After cord traction a woman has shock out of proportion to the blood loss and the fundus is not palpable. What are the diagnosis and action?', 'Uterine inversion; the uterus is replaced manually at once, followed by oxytocin.', 3),
(25, 'Coagulopathy', 'Which blood products are given in PPH with coagulopathy?', 'FFP 4 units for every 6 units of red cells; platelets if the count is below 50 × 10⁹/L; cryoprecipitate if fibrinogen is below 2 g/L.', 3),
(26, 'Secondary PPH', 'What are the commonest causes of secondary PPH?', 'Endometritis and retained products of conception; rarely choriocarcinoma.', 1),
(27, 'Secondary PPH', 'How is secondary PPH with fever and a bulky uterus treated?', 'IV antibiotics (a cephalosporin plus metronidazole), uterotonics, and evacuation if tissue is retained.', 2),
(28, 'Prevention', 'What is active management of the third stage?', 'Oxytocin 10 IU IM within 1 minute, delayed cord clamping (1–3 minutes), controlled cord traction, and uterine massage after delivery of the placenta.', 1),
(29, 'Prevention', 'Which uterotonic is used in the third stage when oxytocin is not available?', 'Misoprostol 600 µg orally.', 2),
(30, 'Complications', 'What is the late endocrine complication of massive PPH?', 'Sheehan syndrome: pituitary necrosis with failure of lactation and amenorrhoea.', 2),
],
'mp': [
(0, 'Types', 'What proportion of twins are dizygotic?', 'About two-thirds; dizygotic twins are always dichorionic diamniotic.', 1),
(1, 'Types', 'Which type of twins results from division of a monozygotic embryo before day 3?', 'Dichorionic diamniotic (DCDA) twins.', 2),
(2, 'Types', 'Which type of twins results from division of a monozygotic embryo on days 4–7?', 'Monochorionic diamniotic (MCDA) twins, about 70% of monozygotic twins.', 2),
(3, 'Types', 'Which type of twins results from division of a monozygotic embryo on days 8–12?', 'Monochorionic monoamniotic (MCMA) twins, about 1%.', 2),
(4, 'Types', 'What results from division of the embryo after day 12?', 'Conjoined twins (very rare).', 1),
(5, 'Risk factors', 'What is the strongest risk factor for twin pregnancy today?', 'Assisted reproduction: IVF with two embryos results in multiple pregnancy in 20–30%.', 1),
(6, 'Diagnosis', 'When is chorionicity best determined?', 'At 11 to 13⁺⁶ weeks on ultrasound.', 1),
(7, 'Diagnosis', 'What does the lambda (twin-peak) sign indicate?', 'Dichorionic twins: a wedge of chorion lies between the two membranes.', 2),
(8, 'Diagnosis', 'What does the T sign indicate?', 'Monochorionic twins: a thin membrane meets the placenta at a right angle.', 2),
(9, 'Diagnosis', 'How is the pregnancy managed when chorionicity is unclear on a late scan?', 'It is managed as monochorionic.', 3),
(10, 'Clinical features', 'What are the signs of twin pregnancy on examination?', 'A uterus that is large for dates, multiple fetal parts (three or more poles) and two fetal hearts at different rates.', 1),
(11, 'Complications', 'How does the risk of pre-eclampsia in twin pregnancy compare with singleton pregnancy?', 'It is about 5 times higher.', 2),
(12, 'Complications', 'What is the main cause of perinatal death in twins?', 'Prematurity.', 1),
(13, 'Complications', 'Why is PPH more common after twin delivery?', 'An overdistended uterus and a large placental bed cause atony.', 2),
(14, 'Twin-to-twin transfusion', 'What causes twin-to-twin transfusion syndrome (TTTS)?', 'Unbalanced arteriovenous anastomoses in a shared monochorionic placenta.', 2),
(15, 'Twin-to-twin transfusion', 'What is the ultrasound picture of TTTS?', 'Monochorionic twins with oligohydramnios around the donor ("stuck" twin) and polyhydramnios around the recipient.', 2),
(16, 'Twin-to-twin transfusion', 'Which twin develops hydrops and heart failure in TTTS?', 'The recipient, which is hypervolaemic and polycythaemic.', 2),
(17, 'Twin-to-twin transfusion', 'How is TTTS treated before 26 weeks?', 'Fetoscopic laser ablation of the placental anastomoses.', 2),
(18, 'Monochorionic twins', 'What is the key difference between TAPS and TTTS?', 'In TAPS there is discordance in haemoglobin with equal liquor volumes; it is diagnosed by middle cerebral artery Doppler.', 3),
(19, 'Monochorionic twins', 'What is the TRAP sequence?', 'An acardiac twin is perfused by a normal "pump" twin, which is at risk of heart failure.', 3),
(20, 'Growth', 'What defines severe weight discordance in twins?', "A difference of more than 30% of the larger twin's weight.", 2),
(21, 'Death of one twin', 'What is the effect of the death of one twin in a monochorionic pair?', 'A risk of up to 25% of death or brain damage in the surviving twin.', 3),
(22, 'Death of one twin', 'Does immediate delivery protect the brain of the surviving monochorionic twin?', 'No. The injury occurs at the moment of death of the co-twin.', 3),
(23, 'Antenatal care', 'How often are growth scans performed in monochorionic and dichorionic twins?', 'Monochorionic: every 2 weeks from 16 weeks. Dichorionic: every 4 weeks from 20 weeks.', 2),
(24, 'Timing of delivery', 'When are uncomplicated DCDA and MCDA twins delivered?', 'DCDA twins at 38 weeks; MCDA twins at 37 weeks.', 2),
(25, 'Timing of delivery', 'How and when are MCMA twins delivered?', 'By caesarean section at 32 weeks, because of the risk of cord entanglement.', 2),
(26, 'Mode of delivery', 'The first twin is cephalic and the second twin is breech. What is the mode of delivery?', 'Vaginal delivery is reasonable.', 2),
(27, 'Mode of delivery', 'The first twin is breech. What is the mode of delivery?', 'Elective caesarean section, because of the risk of locked twins.', 2),
(28, 'Second twin', 'The second twin is transverse with intact membranes. What is the next step?', 'External cephalic version (or internal podalic version and breech extraction).', 3),
(29, 'Second twin', 'The second twin is longitudinal and cephalic, with weak contractions. How is it managed?', 'Oxytocin, followed by artificial rupture of membranes when the head enters the pelvis.', 3),
(30, 'Third stage', 'How is PPH prevented after twin delivery?', 'Active management of the third stage, with an oxytocin infusion for 2–4 hours.', 2),
],
'fgr': [
(0, D, 'Define small for gestational age (SGA).', 'An estimated fetal weight or birth weight below the 10th centile for gestational age.', 1),
(1, D, 'Define fetal growth restriction (FGR).', 'Failure of the fetus to reach its growth potential because of a pathological process.', 1),
(2, D, 'What defines severe SGA?', 'A weight below the 3rd centile.', 1),
(3, D, 'Define low birth weight.', 'A birth weight below 2.5 kg at any gestation.', 1),
(4, D, 'What proportion of SGA babies are constitutionally small?', 'About two-thirds; they have normal Doppler studies and small parents, and are healthy.', 2),
(5, 'Classification', 'What are the timing and typical causes of symmetrical FGR?', 'It is of early onset; the causes are chromosomal abnormalities, congenital infection and drugs.', 2),
(6, 'Classification', 'What are the timing and cause of asymmetrical FGR?', 'It is of late onset and is caused by placental insufficiency, with brain sparing.', 2),
(7, 'Classification', 'Which type of FGR has the worse prognosis?', 'Symmetrical FGR (fewer cells, and often an intrinsic fetal cause).', 2),
(8, 'Causes', 'What is the commonest cause of FGR?', 'Uteroplacental insufficiency, for example in pre-eclampsia.', 1),
(9, 'Causes', 'What are the maternal causes of FGR?', 'Malnutrition and anaemia, hypertension or renal disease, and smoking (also alcohol, antiphospholipid syndrome and warfarin).', 2),
(10, 'Pathophysiology', 'Why does the abdominal circumference fall first in placental FGR?', 'Liver glycogen is consumed and the liver becomes smaller, while the brain is spared.', 3),
(11, 'Pathophysiology', 'Why does placental FGR cause oligohydramnios?', 'Blood is diverted away from the kidneys, so fetal urine output falls.', 3),
(12, 'Screening', 'Which symphysis–fundal height finding should prompt a growth scan?', 'A fundal height more than 3 cm below that expected for dates.', 1),
(13, 'Screening', 'When is uterine artery Doppler performed, and what is the abnormal finding?', 'At 20–24 weeks; a diastolic notch or a high pulsatility index predicts FGR and pre-eclampsia.', 3),
(14, 'Screening', 'Which first-trimester biochemical marker is associated with FGR?', 'A low PAPP-A.', 2),
(15, 'Investigations', 'What is the best single biometric measurement for FGR?', 'The abdominal circumference.', 1),
(16, 'Investigations', 'What is the ideal interval between growth scans?', 'About 3 weeks; shorter intervals give false-positive results.', 2),
(17, 'Investigations', 'Which Doppler study best assesses placental function in FGR?', 'Umbilical artery Doppler.', 1),
(18, 'Investigations', 'What does a low middle cerebral artery pulsatility index indicate?', 'Brain sparing: redistribution of blood flow in the hypoxic fetus.', 3),
(19, 'Investigations', 'What does a high middle cerebral artery peak systolic velocity indicate?', 'Fetal anaemia.', 3),
(20, 'Investigations', 'What does an abnormal a-wave in the ductus venosus indicate?', 'Fetal acidaemia; it is a late, pre-terminal sign and an indication for delivery.', 3),
(21, 'Investigations', 'What is the order of Doppler deterioration in placental FGR?', 'Raised umbilical artery pulsatility index, reduced middle cerebral artery pulsatility index, absent end-diastolic flow, reversed end-diastolic flow, abnormal ductus venosus, and finally an abnormal CTG.', 3),
(22, M, 'What is the plan for FGR with absent end-diastolic flow?', 'Corticosteroids and close CTG monitoring; delivery by 34 weeks, usually by caesarean section.', 3),
(23, M, 'What is the plan for FGR with reversed end-diastolic flow?', 'Corticosteroids if time allows, then delivery (at about 32 weeks) by caesarean section.', 3),
(24, M, 'When is an SGA fetus with normal umbilical artery Doppler delivered?', 'At 37–38 weeks; induction of labour with continuous CTG is acceptable.', 2),
(25, M, 'What is the dose of antenatal corticosteroids before preterm delivery for FGR?', 'Dexamethasone 6 mg IM 12-hourly for four doses.', 2),
(26, M, 'Which principle decides the timing of delivery in FGR?', 'Delivery is indicated when the risk of remaining in the uterus exceeds the risk of prematurity.', 2),
(27, 'Complications', 'What is the common metabolic problem in the growth-restricted newborn?', 'Hypoglycaemia, caused by low glycogen stores.', 1),
(28, 'Complications', 'Why are growth-restricted babies polycythaemic?', 'Chronic hypoxia increases erythropoietin.', 2),
(29, 'Complications', 'Which hypothesis links FGR to adult disease?', 'The Barker hypothesis: adult hypertension, diabetes and heart disease.', 2),
],
'iufd': [
(0, D, 'What is the WHO definition of stillbirth?', 'A baby born with no signs of life at 28 weeks or more, or weighing 1000 g or more.', 1),
(1, D, 'How is fetal death before the viability threshold managed?', 'As a miscarriage.', 1),
(2, 'Causes', 'What is the commonest cause of intrauterine fetal death?', 'It is unexplained in about half of cases.', 1),
(3, 'Causes', 'In Sudan, what is the first test for the cause of intrauterine fetal death with fever and rigors?', 'A blood film for malaria.', 1),
(4, 'Causes', 'What are the maternal causes of intrauterine fetal death?', 'Pre-eclampsia, diabetes, infection (malaria, TORCH infections, syphilis) and antiphospholipid syndrome.', 2),
(5, 'Causes', 'What are the fetal causes of intrauterine fetal death?', 'Congenital anomalies, fetal growth restriction, twin-to-twin transfusion, hydrops and fetomaternal haemorrhage.', 2),
(6, 'Causes', 'What are the placental and cord causes of intrauterine fetal death?', 'Placental abruption, placental insufficiency, a true knot of the cord and cord prolapse.', 2),
(7, 'Clinical features', 'What is the commonest presenting complaint of intrauterine fetal death?', 'Reduced or absent fetal movements.', 1),
(8, 'Clinical features', 'What is the uterine size on examination after intrauterine fetal death?', 'Small for dates; the symphysis–fundal height and maternal weight stop increasing.', 2),
(9, 'Diagnosis', 'Which investigation confirms intrauterine fetal death?', 'Real-time ultrasound showing absent fetal heart activity, ideally confirmed by two operators.', 1),
(10, 'Diagnosis', 'Is an absent fetal heart on Pinard stethoscope or hand-held Doppler diagnostic?', 'No. It is only suggestive; the diagnosis is confirmed by real-time ultrasound.', 2),
(11, 'Diagnosis', 'What is the Spalding sign?', 'Overlapping of the fetal skull bones, about 7 days after death.', 2),
(12, 'Diagnosis', 'What is the Robert sign?', 'Gas in the fetal heart and great vessels; it is the earliest radiological sign (about 12 hours).', 3),
(13, 'Diagnosis', 'What is the Deuel halo sign?', 'Scalp oedema lifts the fat line away from the skull (about 48 hours).', 3),
(14, 'Investigations', 'Why are clotting tests done in intrauterine fetal death?', 'To detect DIC (hypofibrinogenaemia) early: full blood count, clotting screen and fibrinogen.', 2),
(15, 'Investigations', 'Which test is done in an RhD-negative woman with intrauterine fetal death?', 'A Kleihauer test for fetomaternal haemorrhage, followed by anti-D.', 2),
(16, 'Investigations', 'What is the best investigation for the cause after delivery?', 'Post-mortem examination with placental histology; MRI or X-ray if post-mortem examination is declined.', 2),
(17, 'Investigations', 'When is thrombophilia screening performed?', 'About 6 weeks after delivery.', 2),
(18, 'Complications', 'What is the most serious maternal complication of a retained dead fetus?', 'DIC (hypofibrinogenaemia).', 1),
(19, 'Complications', 'Why does DIC occur in intrauterine fetal death?', 'Thromboplastin from the dead fetus enters the maternal circulation.', 2),
(20, 'Complications', 'What is the risk of DIC when a dead fetus is retained for more than 3 weeks?', 'About 30% (about 10% in the first 3 weeks).', 3),
(21, M, 'What are the indications for immediate delivery in intrauterine fetal death?', 'Sepsis or ruptured membranes, DIC, placental abruption and pre-eclampsia.', 2),
(22, M, 'What proportion of women go into spontaneous labour within 3 weeks of intrauterine fetal death?', 'About 85%.', 2),
(23, M, 'What monitoring is required during expectant management?', 'A clotting profile 2–3 times a week; labour is induced if it deteriorates or infection develops.', 3),
(24, M, 'What is the dose of mifepristone before induction for intrauterine fetal death?', '200 mg orally, followed by misoprostol 36–48 hours later.', 2),
(25, M, 'What is the dose of misoprostol for intrauterine fetal death after 28 weeks?', '25 µg vaginally 6-hourly or 25 µg orally 2-hourly.', 3),
(26, M, 'What is the dose of misoprostol for intrauterine fetal death before 27 weeks?', '200 µg vaginally or sublingually every 4–6 hours.', 3),
(27, M, 'Which method of induction is used for intrauterine fetal death after two previous caesarean sections?', 'Routine misoprostol is avoided; a Foley catheter with oxytocin, or caesarean section, is used.', 3),
(28, M, 'Why is artificial rupture of membranes avoided during induction for intrauterine fetal death?', 'Because of the risk of intrauterine infection and sepsis.', 2),
(29, 'Postnatal care', 'Which drug suppresses lactation after intrauterine fetal death?', 'Cabergoline 1 mg orally as a single dose.', 2),
(30, 'Postnatal care', 'When is the follow-up visit after intrauterine fetal death?', 'At about 6 weeks, to discuss the results, the cause, grief and the plan for the next pregnancy.', 1),
],
'lq': [
(0, 'Physiology', 'What is the main source of amniotic fluid after 20 weeks?', 'Fetal urine.', 1),
(1, 'Physiology', 'What is the main route of removal of amniotic fluid?', 'Fetal swallowing, followed by absorption from the gut.', 1),
(2, 'Physiology', 'When is the amniotic fluid volume greatest?', 'At 34–36 weeks (about 900 mL); it is about 600 mL at 40 weeks.', 2),
(3, 'Measurement', 'What is the amniotic fluid index (AFI)?', 'The sum of the deepest vertical pool in each of the four uterine quadrants.', 1),
(4, 'Measurement', 'What is the normal range of the AFI?', '9–25 cm (5–8 cm is borderline).', 1),
(5, 'Polyhydramnios', 'Define polyhydramnios.', 'An AFI above 25 cm or a deepest vertical pool above 8 cm.', 1),
(6, 'Polyhydramnios', 'What is the commonest cause of polyhydramnios?', 'It is idiopathic (and usually mild).', 1),
(7, 'Polyhydramnios', 'What is the commonest maternal cause of polyhydramnios?', 'Diabetes: fetal hyperglycaemia causes polyuria.', 1),
(8, 'Polyhydramnios', 'What are the gastrointestinal causes of polyhydramnios?', 'Oesophageal atresia with tracheo-oesophageal fistula and duodenal atresia: the fetus cannot swallow or absorb the fluid.', 2),
(9, 'Polyhydramnios', 'What is the central nervous system cause of polyhydramnios?', 'Anencephaly (absent swallowing and transudation from the exposed meninges).', 2),
(10, 'Polyhydramnios', 'What is the usual cause of acute polyhydramnios before 20 weeks?', 'Monozygotic twins with twin-to-twin transfusion syndrome.', 3),
(11, 'Polyhydramnios', 'What are the examination findings in polyhydramnios?', 'A uterus that is large for dates and tense, fetal parts and heart sounds that are difficult to detect, and a fluid thrill.', 1),
(12, 'Polyhydramnios', 'What is the differential diagnosis of a uterus that is large for dates?', 'Incorrect dates, twin pregnancy, macrosomia, fibroids, ovarian cyst and ascites.', 2),
(13, 'Polyhydramnios', 'What are the key investigations in polyhydramnios?', 'A detailed ultrasound scan, oral glucose tolerance test, TORCH and syphilis serology, red cell antibodies, and karyotype if an anomaly is found.', 2),
(14, 'Polyhydramnios', 'What are the two dangers when the membranes rupture in polyhydramnios?', 'Cord prolapse and placental abruption caused by sudden decompression.', 2),
(15, 'Polyhydramnios', 'Why does polyhydramnios cause PPH?', 'The overdistended uterus contracts poorly (atony).', 2),
(16, 'Polyhydramnios', 'How is severe symptomatic polyhydramnios (AFI above 40 cm) treated?', 'Amnioreduction with slow drainage; the fluid often re-accumulates.', 2),
(17, 'Polyhydramnios', 'What are the dose and limits of indomethacin for polyhydramnios?', '25 mg orally 6-hourly, only before 32 weeks and for no longer than 72 hours.', 3),
(18, 'Polyhydramnios', 'What are the fetal side effects of indomethacin?', 'Premature closure of the ductus arteriosus and fetal oliguria.', 2),
(19, 'Polyhydramnios', 'How is twin-to-twin transfusion syndrome treated?', 'Laser ablation of the placental anastomoses.', 2),
(20, 'Oligohydramnios', 'Define oligohydramnios.', 'An AFI below 5 cm or a deepest vertical pool below 2 cm.', 1),
(21, 'Oligohydramnios', 'What is the commonest cause of oligohydramnios?', 'Rupture of the membranes.', 1),
(22, 'Oligohydramnios', 'What are the renal causes of oligohydramnios?', 'Renal agenesis (Potter syndrome), dysplastic kidneys and posterior urethral valves.', 2),
(23, 'Oligohydramnios', 'Which drugs cause oligohydramnios?', 'NSAIDs such as indomethacin, ACE inhibitors and angiotensin receptor blockers.', 2),
(24, 'Oligohydramnios', 'What is the main lethal complication of early oligohydramnios?', 'Pulmonary hypoplasia, especially when it begins before about 22 weeks.', 2),
(25, 'Oligohydramnios', 'What are the features of the Potter sequence?', 'A flattened nose, low-set ears, limb contractures, talipes and pulmonary hypoplasia.', 2),
(26, 'Oligohydramnios', 'Why does fetal distress occur in labour with oligohydramnios?', 'Cord compression, without the cushioning effect of the fluid, causes hypoxia and passage of meconium.', 3),
(27, 'Oligohydramnios', 'Is external cephalic version allowed in oligohydramnios?', 'No. It is contraindicated because there is no cushion of fluid.', 2),
(28, 'Oligohydramnios', 'Which antibiotic is given in preterm prelabour rupture of membranes, and at what dose?', 'Erythromycin 250 mg orally 6-hourly for 10 days.', 2),
(29, 'Oligohydramnios', 'How is rupture of membranes at 34–36 weeks or later managed?', 'Labour is induced, unless caesarean section is indicated for another reason.', 2),
]}
QS = {}
def _lv(prefix, levels, emq=None):
    d = {'%s-%d' % (prefix, i + 1): int(x) for i, x in enumerate(levels)}
    for name, lv in (emq or {}).items():
        for k, x in enumerate(lv): d['%s#%d' % (name, k)] = int(x)
    return d
